<?php
require_once __DIR__.'/../../includes/layout.php';require_login();check_csrf();$error='';$id=(int)($_GET['id']??0);$u=current_user();
if($_SERVER['REQUEST_METHOD']==='POST')try{
    if(($_POST['action']??'')==='start')$id=enrollment_start();else enrollment_update($id,$_POST);
    set_flash('success','Enrollment checklist saved. Preparation is separate from school verification.');redirect('enrollment.php?id='.$id);
}catch(InvalidArgumentException $e){$error=$e->getMessage();}
$checklist=$id?enrollment_get($id):null;if($id&&!$checklist){http_response_code(404);exit('Checklist not found.');}
render_header('Enrollment checklist'); ?>
<div class="page-title"><div><span class="eyebrow">ENROLLMENT PREPARATION</span><h1>Enrollment checklist</h1><p>Prepare school-published requirements and follow the reviewing office's feedback.</p></div><a class="btn btn-outline-primary" href="enrollment.php">My checklists</a></div>
<?php if($error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif; ?>
<div class="alert alert-info">A verified checklist does not confirm admission, enrollment, a tuition payment, or an official balance. The school confirms those separately.</div>
<?php if($checklist):$items=enrollment_items($id);$summary=enrollment_summary($items);$owner=$u['role']==='Student'&&(int)$checklist['owner_id']===(int)$u['id']; ?>
<section class="panel"><h2><?= e($checklist['year_name']) ?></h2><p><?= e($checklist['course_name']) ?></p><p><?= e($checklist['full_name'].' · '.($checklist['student_no']??'Student reference unavailable')) ?></p><p><strong><?= e($summary['label']) ?></strong> · <?= $summary['verified'] ?> of <?= $summary['required'] ?> required items verified</p><progress class="w-100" value="<?= $summary['verified'] ?>" max="<?= max(1,$summary['required']) ?>" aria-label="Required enrollment items verified"></progress><p class="mt-3"><?php if($summary['returned']): ?>Next: read the office feedback, correct the returned items, and mark them prepared for another review.<?php elseif($summary['required']&&$summary['required']===$summary['verified']): ?>Next: contact the school for enrollment confirmation and any remaining steps.<?php else: ?>Next: prepare the listed requirements and present them through the reviewing office's published process.<?php endif; ?></p></section>
<div class="row g-4"><div class="col-lg-7"><section class="panel"><h2>My preparation checklist</h2><p>Checking an item means it is prepared. Only an authorized office reviewer can verify it.</p><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="action" value="prepare"><input type="hidden" name="revision" value="<?= (int)$checklist['revision'] ?>"><?php foreach($items as $item): ?><article class="campus-step"><label><input type="checkbox" name="prepared[]" value="<?= (int)$item['id'] ?>" <?= $item['prepared']?'checked':'' ?> <?= !$owner||$item['status']==='Verified'?'disabled':'' ?>> <strong><?= e($item['title']) ?></strong> · <?= $item['required']?'Required':'Optional' ?></label><p><?= e($item['instructions']) ?></p><p>Office: <?= e($item['office_name']) ?> · <strong><?= e($item['status']) ?></strong></p><?php if($item['note']): ?><p class="submission-note">Office feedback: <?= e($item['note']) ?></p><?php endif; ?></article><?php endforeach; ?><?php if($owner): ?><button class="btn btn-primary">Save my preparation</button><?php endif; ?></form></section>
<?php foreach($items as $item):if(can_review_step($item)&&!$owner): ?><section class="panel"><h2>Review: <?= e($item['title']) ?></h2><p><?= e($item['office_name']) ?> · Current status: <?= e($item['status']) ?></p><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="action" value="review"><input type="hidden" name="revision" value="<?= (int)$checklist['revision'] ?>"><input type="hidden" name="item_id" value="<?= (int)$item['id'] ?>"><label for="enrollment-review-<?= (int)$item['id'] ?>">Office decision</label><select id="enrollment-review-<?= (int)$item['id'] ?>" name="status" class="form-select" required><option value="">Choose decision</option><option value="Verified">Verify requirement</option><option value="Returned">Return for correction</option></select><label>Feedback for student<textarea name="note" class="form-control" rows="3" maxlength="600" placeholder="A return requires a reason of at least 5 characters."></textarea></label><button class="btn btn-primary">Save office review</button></form></section><?php endif;endforeach; ?></div>
<div class="col-lg-5"><section class="panel"><h2>Checklist history</h2><?php foreach(rows('SELECT h.*,u.full_name FROM enrollment_history h JOIN users u ON u.id=h.actor_id WHERE checklist_id=? ORDER BY h.id DESC',[$id]) as $h): ?><article class="campus-event"><strong><?= e($h['full_name']) ?></strong><p><?= e($h['body']) ?></p><small><?= e(campus_time($h['created_at'])) ?></small></article><?php endforeach; ?></section><section class="panel"><h2>Need help?</h2><p>Contact the reviewing office before sending documents. This checklist tracks preparation and verification; existing document request uploads remain in My service requests.</p><a href="workflows.php?kind=helpdesk">Ask the school helpdesk →</a></section></div></div>
<?php else:$checklists=rows('SELECT c.*,u.full_name,s.student_no FROM enrollment_checklists c JOIN users u ON u.id=c.owner_id LEFT JOIN students s ON s.user_id=c.owner_id WHERE '.enrollment_scope().' ORDER BY c.id DESC LIMIT 100'); ?>
<?php if($u['role']==='Student'): ?><section class="panel"><h2>Start the active school year's checklist</h2><p>The school publishes requirements for your course. Existing checklists retain their original requirements when school definitions change.</p><form method="post"><?= csrf_field() ?><button class="btn btn-primary" name="action" value="start">Open my enrollment checklist</button></form></section><?php endif; ?>
<section class="panel"><h2><?= in_array($u['role'],['Admin','Super Admin','Teacher'],true)?'Enrollment review workspace':'Available checklists' ?></h2><?php if(!$checklists)empty_state('No enrollment checklists yet','Students can start after the school publishes requirements. Parents can view their linked student’s checklist.');foreach($checklists as $c):$state=enrollment_summary(enrollment_items((int)$c['id'])); ?><article class="campus-event"><strong><?= e($c['year_name'].' · '.$c['course_name']) ?></strong><p><?= e($c['full_name'].' · '.($c['student_no']??'')) ?></p><p><?= e($state['label']) ?></p><a class="btn btn-outline-primary" href="?id=<?= (int)$c['id'] ?>">Open checklist</a></article><?php endforeach; ?></section><?php endif;render_footer(); ?>
